#include <stdio.h>

static void fill(int *a, int n) { for (int i = 0; i < n; i++) a[i] = i + 1; }
static int sum(const int *a, int n) { int s = 0; for (int i = 0; i < n; i++) s += a[i]; return s; }
static void rev(int *a, int n) {
    for (int i = 0, j = n - 1; i < j; i++, j--) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}

int main(void) {
    int a[5];
    fill(a, 5);
    printf("sum=%d\n", sum(a, 5));
    rev(a, 5);
    for (int i = 0; i < 5; i++) printf("%d%s", a[i], i == 4 ? "\n" : " ");
    return 0;
}
